"""Read the immutable build identifier generated by the packaging script."""

from __future__ import annotations

import re
from pathlib import Path


BUILD_NUMBER_FILENAME = "BUILD_NUMBER"
BUILD_NUMBER_PATTERN = re.compile(r"\d{4}\.\d{4}")


def load_build_number(directory: Path | None = None) -> str:
    """Return the packaged DDMM.HHMM build number, or ``dev`` locally."""
    path = (directory or Path(__file__).resolve().parent) / BUILD_NUMBER_FILENAME
    try:
        value = path.read_text(encoding="ascii").strip()
    except OSError:
        return "dev"
    return value if BUILD_NUMBER_PATTERN.fullmatch(value) else "dev"


BUILD_NUMBER = load_build_number()
